// Julie chatbot snippet (base64) — inserted verbatim before </body>.
const SNIPPET_B64 = '';
const snippet = Buffer.from(SNIPPET_B64, 'base64').toString('utf8');

const file = $('GitHub - Get File').first().json;

// Decode current index.html (GitHub returns base64 content).
let html;
if (file.content) {
  html = Buffer.from(String(file.content), 'base64').toString('utf8');
} else if (typeof file.data === 'string') {
  html = file.data;
} else {
  throw new Error('Could not read index.html content from GitHub - Get File output.');
}

// Idempotent: do not insert twice.
let updated;
if (html.includes('<!-- Julie Chatbot -->')) {
  updated = html; // already present, leave unchanged
} else if (html.includes('</body>')) {
  updated = html.replace('</body>', snippet + '\n</body>');
} else {
  updated = html + '\n' + snippet;
}

return [{ json: { fileContent: updated, sha: file.sha, already_present: html.includes('<!-- Julie Chatbot -->') } }];
